class CiscoWanLpbkDir(TextualConvention, Integer32):
    description = "Direction in which looped should be effected:\n                external : loop port traffic back to port. Applicable\n                            only for destructive mode.\n                internal : loop switch's egress traffic back to switch.\n                           Applicable only for destructive mode.\n                forward  : inject OAM loopback cells towards the\n                           switching fabric (ingress). Applicable only\n                           for non-destructive mode.\n                reverse  : inject OAM loopback cells towards the\n                           port (egress). Applicable only for non-\n                           destructive mode."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))
    namedValues = NamedValues(("external", 1), ("internal", 2), ("forward", 3), ("reverse", 4))

